SELECT *,
  FIRST_VALUE({{value_col}}) OVER (
    PARTITION BY {{partition_col}} ORDER BY {{order_col}}
  ) AS first_val,
  LAST_VALUE({{value_col}}) OVER (
    PARTITION BY {{partition_col}} ORDER BY {{order_col}}
    ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
  ) AS last_val
FROM {{table}};
